import { MINUTE_IN_MS, durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import * as repository from './repository.js';
import {
  BOOKING_ACTIVE,
  BOOKING_CANCELLED,
  MAX_DURATION_MINUTES,
  MIN_DURATION_MINUTES,
} from './schema.js';
import type {
  AvailabilityInput,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

const MINUTES_IN_DAY = 1440;
const MAX_WINDOW_MINUTES = 31 * MINUTES_IN_DAY;
const SUGGESTION_WINDOW_MINUTES = 7 * MINUTES_IN_DAY;

export interface Slot {
  startsAt: Date;
  endsAt: Date;
}

export interface Availability {
  roomId: string;
  from: Date;
  to: Date;
  slots: Slot[];
}

function earliest(a: Date, b: Date): Date {
  return isBefore(a, b) ? a : b;
}

function latest(a: Date, b: Date): Date {
  return isBefore(a, b) ? b : a;
}

function addMinutes(instant: Date, minutes: number): Date {
  return new Date(instant.getTime() + minutes * MINUTE_IN_MS);
}

function assertWindow(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('Booking must end after it starts');
  }
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('Booking cannot start in the past', { startsAt });
  }
  const minutes = durationMinutes(startsAt, endsAt);
  if (minutes < MIN_DURATION_MINUTES || minutes > MAX_DURATION_MINUTES) {
    throw validationFailed('Booking duration is out of range', {
      durationMinutes: minutes,
      minDurationMinutes: MIN_DURATION_MINUTES,
      maxDurationMinutes: MAX_DURATION_MINUTES,
    });
  }
}

async function assertRoomExists(roomId: string): Promise<void> {
  const room = await repository.findRoomById(roomId);
  if (!room) {
    throw notFound('Room');
  }
}

async function assertUserExists(userId: string): Promise<void> {
  const user = await repository.findUserById(userId);
  if (!user) {
    throw notFound('User');
  }
}

// Sweeps the active bookings of a room in chronological order and returns the
// gaps left between them. The interval of a booking includes its start and
// excludes its end, so a gap may begin at the exact instant a booking ends.
function freeSlots(bookings: Booking[], from: Date, to: Date, minMinutes: number): Slot[] {
  const slots: Slot[] = [];
  let cursor = from;

  for (const booking of bookings) {
    if (isBefore(cursor, booking.startsAt)) {
      const slotEnd = earliest(booking.startsAt, to);
      if (durationMinutes(cursor, slotEnd) >= minMinutes) {
        slots.push({ startsAt: cursor, endsAt: slotEnd });
      }
    }
    cursor = latest(cursor, booking.endsAt);
    if (!isBefore(cursor, to)) {
      return slots;
    }
  }

  if (durationMinutes(cursor, to) >= minMinutes) {
    slots.push({ startsAt: cursor, endsAt: to });
  }
  return slots;
}

async function nextAvailableStart(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
): Promise<Date | undefined> {
  const horizon = addMinutes(startsAt, SUGGESTION_WINDOW_MINUTES);
  const bookings = await repository.listActiveBetween(roomId, startsAt, horizon);
  const [slot] = freeSlots(bookings, startsAt, horizon, durationMinutes(startsAt, endsAt));
  return slot?.startsAt;
}

async function conflictFor(
  conflict: Booking,
  roomId: string,
  startsAt: Date,
  endsAt: Date,
): Promise<AppError> {
  const suggestion = await nextAvailableStart(roomId, startsAt, endsAt);
  return bookingConflict(conflict.id, suggestion ? { nextAvailableStart: suggestion } : {});
}

