  await assertRoomExists(input.roomId);
  await assertUserExists(input.userId);

  const conflict = await repository.findOverlapping(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw await conflictFor(conflict, input.roomId, startsAt, endsAt);
  }

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

